const iso=ms=>new Date(ms).toISOString();
const fnv=s=>{ let h=0x811c9dc5; s=String(s); for(let i=0;i<s.length;i++){ h^=s.charCodeAt(i); h=Math.imul(h,0x01000193); } return h>>>0; };   // FNV-1a, written here on its own (not the page's sfHash)
const near=(a,b,e)=>typeof a==='number' && Math.abs(a-b)<=(e||1e-12);
const honest='Many overlapping groups were checked. ‘Holding up’ and ‘Struggling’ need the 95% range to clear zero and a 10% false-discovery-rate screen. Leads are not proof; the 1,000-bet test is the Scorecard.';   // the card’s honest line (S5)
const honest2=honest+' ‘Leaning’ needs only the 90% range to clear zero.';   // v5.07 (fixer): the card also says what ‘Leaning’ needs
const chk0='In this view no group has 100 outcomes on 50 games yet.', chk1='In this view only 1 group has 100 outcomes on 50 games, so the screen checked it alone.', chkN=n=>'In this view the screen checked the '+n+' groups with 100 outcomes on 50 games.', chkF=' Filters are on, so only the groups in this filtered view were checked.';   // v5.07 (fixer): how many groups the many-group check covered
