// ---- fixtures (the plan's Appendix B) ----
// one settled prop: game gi of group tag (its own game text), start = Nov 1 00:00Z + gi × 20 min (all before NOW), saved 2 h before the start
function prop(tag, i, gi, o){ const st=Date.parse('2026-11-01T00:00:00Z')+gi*20*60e3; return Object.assign({id:'b'+tag+'-'+i, key:tag+'-'+i, kind:'prop', sport:'NHL', book:'Caesars', name:'P '+tag+' '+i, market:'2.5 Shots On Goal', side:'O', odds:'+100', stake:1,
  game:'Away'+tag+'x'+gi+' @ Home'+tag+'x'+gi, start:iso(st), date:iso(st).slice(0,10), result:'win', gradedBy:'manual', snap:{at:iso(st-2*H)}}, o||{}); }
const stakeOf=i=>+(1+((i*37)%10)/10).toFixed(2);   // 1.00 … 1.90, never a round lattice (an exact 0 at a range end is possible with whole-dollar stakes)
// B: by Sport, 10 rows of 100+ outcomes on 50+ games. NHL: 120 bets on 60 games at +300, 36 wins (raw 95% range clears zero, p 0.011–0.024 under any seed, above the 0.01 bar);
// the 9 others: 100 bets on 50 games at +100, one win and one loss of the same stake in every game (ROI exactly 0, p = 1).
function ctxB(){ const L=[]; const N=120, w=36, wins=new Set(); for(let k=0;k<w;k++) wins.add(Math.floor((k+0.5)*N/w));
  for(let i=0;i<N;i++) L.push(prop('nhl', i, Math.floor(i/2), {sport:'NHL', odds:'+300', stake:stakeOf(i), result:wins.has(i)?'win':'loss'}));
  ['NBA','NFL','NCAAF','NCAAB','MLB','EPL','MLS','WNBA','UCL'].forEach((sp,s)=>{ for(let i=0;i<100;i++){ const g=Math.floor(i/2); L.push(prop(sp.toLowerCase(), i, 200+s*60+g, {sport:sp, market:'1.5 Points', stake:+(1+(g%7)/10).toFixed(2), result:i%2?'loss':'win'})); } });
  return L; }
// C: by Book, one row per gate edge: [book, outcomes, games, pattern]; 'up' = 80% wins at +100, 'down' = 20% wins, 'lean' = 120 bets on 60 games at +300 with 39 wins
const C_ROWS=[['Gate 29 on 15',29,15,'up'],['Gate 30 on 14',30,14,'up'],['Gate 30 on 15',30,15,'up'],['Gate 49 on 25',49,25,'up'],['Gate 50 on 24',50,24,'up'],['Gate 50 on 25',50,25,'up'],
  ['Gate 99 on 50',99,50,'up'],['Gate 100 on 49',100,49,'up'],['Gate 100 on 50',100,50,'up'],['Down 100 on 50',100,50,'down'],['Down 50 on 25',50,25,'down'],['Lean 120 on 60',120,60,'lean']];
function ctxC(){ const L=[]; let g0=0; C_ROWS.forEach(([book,n,G,pat],r)=>{ const lw=new Set(); if(pat==='lean') for(let k=0;k<39;k++) lw.add(Math.floor((k+0.5)*n/39));
    for(let i=0;i<n;i++){ const win=pat==='up'?(i%5)!==0:pat==='down'?(i%5)===0:lw.has(i), g=pat==='lean'?Math.floor(i/2):(i%G);
      L.push(prop('c'+r, i, g0+g, {book, sport:'NBA', market:'1.5 Points', odds:pat==='lean'?'+300':'+100', stake:stakeOf(i), result:win?'win':'loss'})); }
    g0+=G+5; }); return L; }
// D: one ticket of each kind for Expected vs actual, flat $1, CLV and the many places money is counted (all at "Fixture Book", each on its own game)
function ctxD(){ const st=Date.parse('2026-11-10T00:00:00Z'), pre=iso(st-3*H), post=iso(st+30*60e3);
  const b=(id,o)=>Object.assign({id, key:id, kind:'prop', sport:'NBA', book:'Fixture Book', name:'D '+id, market:'1.5 Threes', side:'O', odds:'-110', stake:10, game:'Away'+id+' @ Home'+id, start:iso(st), date:'2026-11-09', result:'win', gradedBy:'manual', snap:{at:pre}}, o||{});
  return [
    b('e1',{odds:'+100', stake:10, result:'win',  closing:'-110', snap:{at:pre, act:0.55, actNet:0.10, model:0.58, market:0.52}}),   // eligible: E 1.00, A +10.00, CLV 0.5238/0.5 − 1
    b('e2',{odds:'-110', stake:5,  result:'loss', closing:'-105', snap:{at:pre, act:0.55, actNet:0.05, model:0.57, market:0.53}}),   // eligible: E 0.25, A −5.00
    b('fr',{odds:'+100', stake:4, free:true, result:'win', snap:{at:pre, act:0.55, actNet:0.10}}),                       // free: out of E/A and flat $1
    b('so',{odds:'+100', stake:6, result:'loss', sold:{price:4}, snap:{at:pre, act:0.55, actNet:0.10}}),                   // sold: out
    b('pa',{kind:'parlay', sport:'PARLAY', market:'2-pick parlay', name:'2-pick parlay', odds:'+260', stake:2, result:'loss', parlay:{legs:2}, snap:{at:pre, act:0.3, actNet:0.08}}),   // parlay: out
    b('rc',{odds:'+100', stake:3, result:'win', snap:{at:pre}, forecastRecovery:{act:0.6, policy:'forecast-recovery-v1'}}),   // recovered (the v5.06 field): shown apart
    b('mo',{odds:'+100', stake:7, result:'loss', snap:{at:pre, act:0.57, actNet:0.14, model:0.57, modelOnly:true}}),     // model fallback (no market to blend)
    b('lg',{odds:'+100', stake:8, result:'win', snap:{at:pre, model:0.6}}),                                               // model fallback (an older bet: model only)
    b('ps',{odds:'+100', stake:9, result:'win', snap:{at:post, act:0.55, actNet:0.10}}),                                   // saved after the start: out (not counted apart)
    b('pu',{odds:'+100', stake:2, result:'push', closing:'+105', snap:{at:pre}}),                                         // push: settled, flat $1 counts 0, no forecast
    b('op',{odds:'+100', stake:5, start:iso(NOW+5*H), date:'2026-11-15', result:undefined, snap:{at:iso(NOW-H), act:0.55, actNet:0.10}})];   // open: not settled
}
// E (v5.07 fixer): four books with La Contadora’s forecast on 40 games each (dollar ranges with signs in Expected vs actual, at every width), and the
// no-sport props: Blocks on an event whose other tickets are all NBA (mapped), Player Goals on an event with NHL and NBA tickets (unmapped), Points with no event (unmapped)
function ctxE(){ const L=[], t0=Date.parse('2026-11-01T00:00:00Z');
  ['Alpha Book','Beta Book','Gamma Book','Delta Book'].forEach((bk,r)=>{ for(let i=0;i<40;i++){ const gi=300+r*50+i, win=((i*7+r*3)%10)<(r%2?4:6);
    L.push(prop('e'+r, i, gi, {book:bk, sport:'NBA', market:'20.5 Points', odds:'+100', stake:+(10+((i*13)%17)*3.7).toFixed(2), result:win?'win':'loss', snap:{at:iso(t0+gi*20*60e3-2*H), act:0.55, actNet:0.06}})); } });
  const ev=(id, i, gi, o)=>prop('ev'+id, i, gi, Object.assign({book:'Novig'}, o));
  L.push(ev('a',0,500,{sport:'NBA', market:'20.5 Points', nvEvent:'nvA'}), ev('a',1,500,{sport:'NBA', market:'8.5 Rebounds', nvEvent:'nvA'}), ev('a',2,500,{sport:'', market:'0.5 Blocks', nvEvent:'nvA'}),
    ev('b',0,501,{sport:'NHL', market:'0.5 Points', nvEvent:'nvB'}), ev('b',1,501,{sport:'NBA', market:'20.5 Points', nvEvent:'nvB'}), ev('b',2,501,{sport:'', market:'0.5 Player Goals', nvEvent:'nvB'}),
    ev('c',0,502,{sport:'', market:'1.5 Points'}));
  return L; }
async function open(B, log, o){ o=o||{}; const ctx=await B.newContext({timezoneId:'America/Chicago', viewport:{width:o.width||1280, height:1000}}); await ctx.clock.install({time:new Date(NOW)});
  await ctx.addInitScript(([L,U])=>{ try{ if(sessionStorage.getItem('s')) return; sessionStorage.setItem('s','1'); localStorage.clear(); localStorage.setItem('mbev.log',JSON.stringify(L)); if(U) localStorage.setItem('mbev.reportsUi',JSON.stringify(U)); }catch(e){} }, [log, o.ui||null]);
  const p=await ctx.newPage(); const errs=[]; p.on('pageerror',e=>errs.push(e.message));
  await p.route('**/*',r=>{ const u=r.request().url(); if(u.startsWith('http://app.test/')) return r.fulfill({contentType:'text/html',body:html}); if(/0xbeta/.test(u)) return r.fulfill({contentType:'application/json',body:'{}'}); if(/espn/.test(u)) return r.fulfill({contentType:'application/json',body:'{"events":[]}'}); return r.abort(); });
  await p.goto('http://app.test/'); await p.waitForTimeout(1300); return {ctx, p, errs}; }
