// layout and the v5.04 rules inside the So far card and the By table (as v504a / v504b check them for the whole page)
const LAYOUT=()=>{ const out={side:document.documentElement.scrollWidth-innerWidth, out:[], inner:null, small:[], plus:0, minus:0, bad:[], wrong:[], labels:[], thead:'', signs:0, split:[]};
  document.querySelectorAll('#rpPanel .rp-tw, #rpPanel .rp-sofar, #rpPanel .rp-ctl').forEach(e=>{ const r=e.getBoundingClientRect(); if(r.width && (r.right>innerWidth+1 || r.left<-1)) out.out.push(e.className+' '+Math.round(r.right)); });
  const tw=document.querySelector('#rpBreak .rp-tw'); out.inner=tw?tw.scrollWidth-tw.clientWidth:null; const th=document.querySelector('#rpBreak thead'); out.thead=th?getComputedStyle(th).display:'';
  const vis=e=>{ const r=e.getBoundingClientRect(), cs=getComputedStyle(e); return r.width>0 && r.height>0 && cs.visibility!=='hidden' && cs.display!=='none'; };
  const bef=el=>getComputedStyle(el,'::before').content;
  document.querySelectorAll('#rpSoFar *, #rpBreak *').forEach(el=>{ if(!vis(el)) return;
    if([...el.childNodes].some(n=>n.nodeType===3 && n.textContent.trim()) && parseFloat(getComputedStyle(el).fontSize)<12) out.small.push(el.tagName.toLowerCase()+'.'+el.className+' '+getComputedStyle(el).fontSize);
    const t=el.textContent.replace(/\s+/g,' ').trim(), m=t.match(/^([+−])\$(\d[\d,]*\.\d\d)/);
    if(m && +m[2].replace(/,/g,'')>0 && ![...el.children].some(c=>c.textContent.replace(/\s+/g,' ').trim()===t)){ if(m[1]==='+'){ out.plus++; if(!/▲ "$/.test(bef(el))) out.bad.push('+ no ▲: '+t.slice(0,30)); } else { out.minus++; if(!/▼ "$/.test(bef(el))) out.bad.push('− no ▼: '+t.slice(0,30)); } } });
  document.querySelectorAll('#rpSoFar .d-up, #rpSoFar .d-dn, #rpBreak .d-up, #rpBreak .d-dn').forEach(el=>{ if(!vis(el)) return; const t=el.textContent.replace(/\s+/g,' ').trim(), up=el.classList.contains('d-up');
    if(up ? /−|-(?=\d|\$)/.test(t) : /\+/.test(t)) out.wrong.push((up?'d-up ':'d-dn ')+t.slice(0,30)); if(!(up?/▲ "$/:/▼ "$/).test(bef(el))) out.wrong.push('no arrow drawn: '+t.slice(0,30)); });
  ['rpSoFar','rpBreak'].forEach(id=>{ const root=document.getElementById(id); if(!root) return; const tw=document.createTreeWalker(root, NodeFilter.SHOW_TEXT); let t;   // v5.07 (fixer): no + or − ends a line while its amount starts the next
    while((t=tw.nextNode())){ const s=t.nodeValue, re=/[−+](?=[$\d])/g; let m; while((m=re.exec(s))){ out.signs++; const a=document.createRange(); a.setStart(t,m.index); a.setEnd(t,m.index+1); const b=document.createRange(); b.setStart(t,m.index+1); b.setEnd(t,Math.min(s.length,m.index+2));
      const ra=a.getClientRects()[0], rb=b.getClientRects()[0]; if(ra && rb && rb.top>ra.bottom-2) out.split.push(s.slice(Math.max(0,m.index-14), m.index+10)); } } });
  if(innerWidth<=999) document.querySelectorAll('#rpBreak td[data-l]').forEach(td=>{ if(bef(td).indexOf(td.dataset.l+': ')!==1) out.labels.push(td.dataset.l+' → '+bef(td)); });
  return out; };
